// Deploy 1: both paths. Runs that started before this deploy skip the grill.
if (patched("grill-step")) {
  if (!(await readinessAndGrill(t, run))) return "parked";
}

// Deploy 2, once no run that started before deploy 1 is open: only the new path, marker still written.
deprecatePatch("grill-step");
if (!(await readinessAndGrill(t, run))) return "parked";

// Deploy 3, once no run that started before deploy 2 is open: plain code.
if (!(await readinessAndGrill(t, run))) return "parked";

export async function slots(agent: string, holders: string[] = [], waiting: string[] = []): Promise<void> {
  setHandler(request, (id) => { waiting.push(id); });
  setHandler(release, (id) => { holders = holders.filter((h) => h !== id); });
  while (workflowInfo().historyLength < 5000) {
    await condition(() => waiting.length > 0 && holders.length < (SLOTS[agent] ?? 1));
    const holder = waiting.shift()!;
    holders.push(holder);
    await getExternalWorkflowHandle(holder).signal(slotGranted);
  }
  await continueAsNew<typeof slots>(agent, holders, waiting);
}

