// workflows.mjs, deploy 2 of the patch: only the new path, and the marker is still written
import { condition, defineSignal, deprecatePatch, proxyActivities, setHandler } from '@temporalio/workflow';

const { grill, writePlan, openPr } = proxyActivities({ startToCloseTimeout: '1 minute' });

export const approve = defineSignal('approve');

export async function ticketToPr(ticket) {
  let approvedBy;
  setHandler(approve, (who) => {
    approvedBy = who;
  });
  deprecatePatch('grill-step');
  await grill(ticket);
  await writePlan(ticket);
  await condition(() => approvedBy !== undefined, '1 day');
  await openPr(ticket);
  return `${ticket}: approved by ${approvedBy}`;
}

